from pathlib import Path
import json,hashlib,collections,shutil
import rosbag
ROOT=Path('/media/zhuyupei/SanStand/实验记录/Robot-Controller')
S=ROOT/'ros_log/full_latest_ros_20261009T003407Z';R=ROOT/'grasp_records/20261009T022026.944578Z_cca56e3000b84b5289c1adfa0e09a9bb';OUT=S/'gen7_registration_analysis'
start=1791512499989999055
requests=[];acks=[];statuses=[];phases=[];false_objects=[]
with rosbag.Bag(str(R/'keyframes.bag')) as b:
 for topic,m,t in b.read_messages(topics=['/grasp_mode/observe_return_measurement_request','/grasp_mode/observe_return_measurement_ack','/perception/unknown/detector_status','/perception/object','/grasp/near_field_phase']):
  if topic.endswith('measurement_request'):requests.append(dict(received_ns=t.to_nsec(),message=json.loads(m.data)))
  elif topic.endswith('measurement_ack'):acks.append(dict(received_ns=t.to_nsec(),message=json.loads(m.data)))
  elif topic.endswith('detector_status') and t.to_nsec()>=start:
   d=json.loads(m.data);g=d.get('geometry_metrics',{});o=d.get('observation_measurement',{})
   statuses.append(dict(received_ns=t.to_nsec(),source_ns=d.get('source_stamp_ns'),state=d.get('state'),detail=d.get('detail'),target_lost=d.get('target_lost'),first_loss=d.get('first_loss'),anchor_source_stamp_ns=d.get('anchor_source_stamp_ns'),measurement_state=o.get('state'),measurement_reason=o.get('reason'),measurement_sources=o.get('source_stamps_ns'),rgb_attempts=g.get('rgb_search_attempts'),rgb_margin_px=g.get('rgb_search_margin_px'),support_reference_max_distance_m=g.get('support_reference_max_distance_m')))
  elif topic=='/perception/object' and t.to_nsec()>=start and not m.detected:false_objects.append(dict(received_ns=t.to_nsec(),source_ns=m.header.stamp.to_nsec()))
  elif topic.endswith('near_field_phase') and m.active:phases.append(dict(received_ns=t.to_nsec(),phase_id=m.phase_id,start_ns=m.header.stamp.to_nsec(),reference_source_ns=m.reference_source_stamp.to_nsec(),target_track_id=m.reference_target_track_id))
report=dict(schema=1,record=str(R),result='failed_after_successful_observation_and_requalification',first_causal_failure='OBSERVE_RETURN_REGISTRATION_FAILED: YAW_BOUND_EXCEEDED',downstream_symptom='NEAR_FIELD_PLAN_PHASE_INVALID',observation_motion_completed=True,contact_motion_started=False,physical_grasp_success=False,arrived_settle=dict(log_stamp_sec=1791512499.983232,independent_samples=9,span_rad=0.),arrival_source_threshold_ns=start,requests=requests,acks=acks,near_field_phases=phases,arrival_and_following_statuses=statuses,false_objects_after_arrival=false_objects,normal_ready_frames_after_receipt=sum(x['detail']=='tracked' and x['state']=='ready' for x in statuses),original_geometry_reconstruction='reconstruction.json',independent_texture_diagnostic='texture_registration_deduplicated.json',conclusions=['Three-frame arrival proof and dual consumer acknowledgement completed in approximately 0.803 seconds; ordinary tracked frames continued.','Original reference reconstructed bit-identically from recorded three RGB-D frames and timestamp TF; moving source is the exact task-referenced single frame.','Original geometry registration chooses 13.5331729 degree yaw and fails the unmodified 10 degree limit; its other original endpoint gates pass.','Independent mutually matched real-depth texture points prefer approximately zero yaw; deduplicated ORB tests yield -1.077 to +1.428 degrees. Original 13.53 degree transform has 6.0-7.1 mm errors on those agreed texture correspondences.','This supports a partial-view geometric correspondence bias; it is not sufficient by itself to prove a new execution-authoritative transform or justify relaxing any gate.','Feature correspondences are sparse and predominantly distributed along printed text; alternate AKAZE provides only weak corroboration.'],no_ros_actions=True,temperature_values_read=False)
for f in ['analyze_gen7_registration.py','analyze_gen7_texture_registration.py','analyze_gen7_texture_registration_deduplicated.py']:
 shutil.copyfile(Path('.runtime')/f,OUT/f)
report['artifacts_sha256']={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in OUT.iterdir() if p.is_file() and p.name!='analysis.json'}
(OUT/'analysis.json').write_text(json.dumps(report,indent=2,ensure_ascii=False)+'\n')
print(json.dumps(dict(analysis=str(OUT/'analysis.json'),sha256=hashlib.sha256((OUT/'analysis.json').read_bytes()).hexdigest(),following_ready=report['normal_ready_frames_after_receipt'],post_arrival_false_objects=len(false_objects),status_counts=dict(collections.Counter(x['detail'] for x in statuses))),ensure_ascii=False))
